package domain

import (
	"context"
	"reflect"
	"testing"
)

func TestCandidateInheritanceImpactBeforeRevisionAllocation(t *testing.T) {
	// Persisted source and expectations are handwritten, not generated by Calculate.
	base := []Record{
		{ID: "f", Revision: "f-v1", RevisionNo: 1, Date: "2026-01-01", End: "2026-03-01", Type: "CREATE", State: "active", Data: BUData{Name: "甲"}},
		{ID: "s1", Revision: "s1-v1", RevisionNo: 1, Date: "2026-03-01", End: "2026-04-01", Type: "DEACTIVATE", State: "inactive", InheritedRecord: "f", InheritedRevision: "f-v1", Data: BUData{Name: "甲"}},
		{ID: "r1", Revision: "r1-v1", RevisionNo: 1, Date: "2026-04-01", End: "2026-05-01", Type: "REACTIVATE", State: "active", Data: BUData{Name: "乙"}},
		{ID: "s2", Revision: "s2-v1", RevisionNo: 1, Date: "2026-05-01", End: "2026-06-01", Type: "DEACTIVATE", State: "inactive", InheritedRecord: "r1", InheritedRevision: "r1-v1", Data: BUData{Name: "乙"}},
		{ID: "r2", Revision: "r2-v1", RevisionNo: 1, Date: "2026-06-01", Type: "REACTIVATE", State: "active", Data: BUData{Name: "丙"}},
	}
	original := append([]Record(nil), base...)
	for _, tc := range []struct {
		name, value string
		index       int
		noChange    bool
	}{{"first", "甲2", 0, false}, {"reactivate", "乙2", 2, false}, {"same_value", "乙", 2, true}} {
		t.Run(tc.name, func(t *testing.T) {
			r, s := base[tc.index], base[tc.index+1]
			got, err := Calculate(context.Background(), base, "f", "2020-01-01", []Item{{ID: "fix", Action: "CORRECT", RecordID: r.ID, ExpectedRevision: r.Revision, Changes: PatchFromFields(map[string]*string{"name": textValue(tc.value)})}})
			if err != nil {
				t.Fatal(err)
			}
			if tc.noChange {
				if !got.NoChange || len(got.Impact.StructuralChanges) != 0 || len(got.Impact.AffectedRecordIDs) != 0 || !reflect.DeepEqual(got.Records, base) {
					t.Fatal("same value manufactured a pending revision", got)
				}
				return
			}
			want := Impact{
				DataAffectedRanges: []Range{{Start: r.Date, End: textValue(s.End)}},
				StructuralChanges:  []StructuralChange{{RecordID: s.ID, BeforeRevision: textValue(s.Revision), Facets: []string{"INHERITANCE"}}},
				AffectedRecordIDs:  []string{r.ID, s.ID},
				PeriodChanges:      []PeriodChange{},
			}
			if got.NoChange || !reflect.DeepEqual(got.Impact, want) {
				t.Fatalf("impact: got %+v; want %+v", got.Impact, want)
			}
			wantRecords := append([]Record(nil), base...)
			for _, i := range []int{tc.index, tc.index + 1} {
				wantRecords[i].Data.Name = tc.value
			}
			wantRecords[tc.index+1].InheritedRevision = ""
			if !reflect.DeepEqual(got.Records, wantRecords) || !reflect.DeepEqual(base, original) {
				t.Fatal("pending inheritance, independent snapshot or original source changed", got.Records)
			}
		})
	}
}
